div.script:
"use strict";
const API = "https://shrill-fire-ad73.wasubanli356.workers.dev/api/games";
const PAGE_SIZE = 500;
const $ = id => document.getElementById(id);
let games = [], activeUrl = "", controller = null;

function safeHttpURL(value) {
  if (typeof value !== "string" || !value.trim()) return "";
  try { const u = new URL(value); return /^https?:$/.test(u.protocol) ? u.href : ""; }
  catch { return ""; }
}
function unpack(payload) {
  const rows = Array.isArray(payload) ? payload : payload?.games;
  if (!Array.isArray(rows)) throw new Error("API response does not contain a games array");
  return rows.map((g, i) => ({
    id: String(g.id ?? `${g.source ?? "game"}-${i}`),
    title: String(g.title ?? g.name ?? "Untitled game"),
    url: safeHttpURL(g.url ?? g.gameUrl ?? g.href ?? g.link),
    thumbnail: safeHttpURL(g.thumbnail ?? g.image ?? g.cover ?? g.icon ?? g.thumb),
    source: String(g.source ?? "Unknown source")
  })).filter(g => g.url);
}
async function getPage(page, signal) {
  const url = new URL(API);
  url.searchParams.set("limit", String(PAGE_SIZE));
  url.searchParams.set("page", String(page));
  const response = await fetch(url.href, {headers:{Accept:"application/json"}, cache:"no-store", signal});
  if (!response.ok) throw new Error(`API returned HTTP ${response.status} on page ${page}`);
  return response.json();
}
async function fetchAllGames() {
  if (controller) controller.abort();
  controller = new AbortController();
  const signal = controller.signal;
  const reload = $("reload");
  reload.disabled = true;
  $("status").textContent = "Fetching the full catalog from all API pages…";
  $("games").replaceChildren(); $("empty").style.display = "none";
  try {
    const first = await getPage(1, signal);
    let combined = unpack(first);
    const total = Number(first?.total);
    const pageSize = Number(first?.limit) || PAGE_SIZE;
    let totalPages = Number(first?.totalPages);
    if (!Number.isFinite(totalPages) || totalPages < 1) {
      totalPages = Number.isFinite(total) && total > combined.length
        ? Math.ceil(total / pageSize) : 1;
    }
    // If the API ignores pagination and already returns the entire catalog, don't refetch it.
    if (Number.isFinite(total) && combined.length >= total) totalPages = 1;
    if (totalPages > 1) {
      let completed = 1;
      for (let start = 2; start <= totalPages; start += 4) {
        const batchPages = [];
        for (let p = start; p < Math.min(start + 4, totalPages + 1); p++) batchPages.push(p);
        const batch = await Promise.all(batchPages.map(p => getPage(p, signal)));
        for (const payload of batch) combined.push(...unpack(payload));
        completed += batch.length;
        $("status").textContent = `Fetching all games… ${Math.min(completed * pageSize, total || combined.length).toLocaleString()} loaded`;
      }
    }
    // Preserve the same game URL when it appears in different sources; only remove exact duplicates.
    const seen = new Set();
    games = combined.filter(game => {
      const key = `${game.source}|${game.url}`;
      if (seen.has(key)) return false;
      seen.add(key); return true;
    });
    render();
    const failed = Array.isArray(first?.failedSources) ? first.failedSources.length : 0;
    const totalText = Number.isFinite(total) ? ` API reports ${total.toLocaleString()} entries.` : "";
    const failedText = failed ? ` ${failed} source(s) failed on the API; those games cannot be fetched until the Worker source errors are fixed.` : "";
    $("status").textContent = `Loaded ${games.length.toLocaleString()} games across all returned sources.${totalText}${failedText}`;
  } catch (error) {
    if (error.name !== "AbortError") $("status").textContent = `Could not load the full catalog: ${error.message}. Check the Worker API and CORS settings.`;
  } finally {
    reload.disabled = false;
    if (controller?.signal === signal) controller = null;
  }
}
function render() {
  const q = $("search").value.trim().toLowerCase();
  const shown = games.filter(g => !q || g.title.toLowerCase().includes(q) || g.source.toLowerCase().includes(q));
  const frag = document.createDocumentFragment();
  for (const game of shown) {
    const card = document.createElement("article"); card.className = "game";
    if (game.thumbnail) {
      const img = document.createElement("img"); img.className = "cover"; img.src = game.thumbnail; img.alt = ""; img.loading = "lazy"; img.referrerPolicy = "no-referrer";
      img.onerror = () => { const p = document.createElement("div"); p.className = "no-cover"; p.textContent = "▣"; img.replaceWith(p); };
      card.append(img);
    } else { const p = document.createElement("div"); p.className = "no-cover"; p.textContent = "▣"; card.append(p); }
    const info = document.createElement("div"); info.className = "info";
    const title = document.createElement("h2"); title.textContent = game.title;
    const source = document.createElement("div"); source.className = "source"; source.textContent = game.source;
    const actions = document.createElement("div"); actions.className = "actions";
    const play = document.createElement("button"); play.textContent = "Play"; play.addEventListener("click", () => playGame(game));
    const open = document.createElement("button"); open.className = "secondary"; open.textContent = "Open link"; open.addEventListener("click", () => window.open(game.url, "_blank", "noopener,noreferrer"));
    actions.append(play, open); info.append(title, source, actions); card.append(info); frag.append(card);
  }
  $("games").replaceChildren(frag); $("empty").style.display = shown.length ? "none" : "block";
}
function playGame(game) {
  activeUrl = game.url; $("playing-title").textContent = game.title; $("frame").src = game.url; $("player").style.display = "block";
  $("player").scrollIntoView({behavior:"smooth", block:"start"});
}
function closeGame() { $("frame").src = "about:blank"; $("player").style.display = "none"; activeUrl = ""; }
$("search").addEventListener("input", render);
$("reload").addEventListener("click", fetchAllGames);
$("close").addEventListener("click", closeGame);
$("open-tab").addEventListener("click", () => { if (activeUrl) window.open(activeUrl, "_blank", "noopener,noreferrer"); });
fetchAllGames();
